CREATE OR ALTER PROCEDURE dbo.SP_GUARDAR_RESULTADO  (        @EvaluacionId      INT      , @VersCaractId      INT      , @ResultadoTexto    VARCHAR(500) = NULL      , @ResultadoNumerico DECIMAL(18,6) = NULL      , @Cumple            BIT = NULL      , @Observacion       VARCHAR(1000) = NULL      , @Usuario           VARCHAR(100)  )  AS  BEGIN        SET NOCOUNT ON;      SET XACT_ABORT ON;          DECLARE            @EstadoEvaluacionId       INT          , @EstadoEnProcesoId        INT          , @VersionId                INT          , @VersionFaseId            INT          , @EvaluacionPadreId        INT            , @TipoCriterioId           INT          , @TipoCriterio             VARCHAR(100)          , @TipoResultado            VARCHAR(20)            , @ValorCuantitativoInicial DECIMAL(18,6)          , @ValorCuantitativoFinal   DECIMAL(18,6)          , @ValorCuantitativoIgual   DECIMAL(18,6)          , @ValorCualitativo         VARCHAR(1000)            , @CumpleCalculado          BIT          , @EvaluacionResultadoId    INT;          BEGIN TRY            BEGIN TRANSACTION;              /* =========================================================             1. VALIDAR EVALUACION             ========================================================= */            SELECT                @EstadoEvaluacionId = E.EstadoEvaluacionId              , @VersionId          = L.VersionId              , @VersionFaseId      = E.VersionFaseId              , @EvaluacionPadreId  = E.EvaluacionPadreId            FROM dbo.EVALUACION E            INNER JOIN dbo.LOTE L              ON L.LoteId = E.LoteId            WHERE E.EvaluacionId = @EvaluacionId            AND E.Estado = 'ACTIVO'            AND L.Estado = 'ACTIVO';              IF @EstadoEvaluacionId IS NULL          BEGIN                RAISERROR(                  'La evaluación no existe o se encuentra inactiva.',                  16,                  1              );            END;              /* =========================================================             2. OBTENER ESTADO EN_PROCESO             ========================================================= */            SELECT              @EstadoEnProcesoId = EstadoEvaluacionId            FROM dbo.ESTADO_EVALUACION            WHERE Codigo = 'EN_PROCESO';              IF @EstadoEnProcesoId IS NULL          BEGIN                RAISERROR(                  'No existe el estado de evaluación EN_PROCESO.',                  16,                  1              );            END;              /* =========================================================             3. VALIDAR ESTADO DE LA EVALUACION             ========================================================= */            IF @EstadoEvaluacionId <> @EstadoEnProcesoId          BEGIN                RAISERROR(                  'Solo se pueden registrar resultados en una evaluación EN_PROCESO.',                  16,                  1              );            END;              /* =========================================================             4. VALIDACIONES GENERALES             ========================================================= */            IF @ResultadoTexto IS NOT NULL             AND @ResultadoNumerico IS NOT NULL          BEGIN                RAISERROR(                  'Solo puede registrar un tipo de resultado.',                  16,                  1              );            END;              IF LEN(ISNULL(@ResultadoTexto, '')) > 500          BEGIN                RAISERROR(                  'El resultado supera los 500 caracteres.',                  16,                  1              );            END;              IF LEN(ISNULL(@Observacion, '')) > 1000          BEGIN                RAISERROR(                  'La observación supera los 1000 caracteres.',                  16,                  1              );            END;              /* =========================================================             5. VALIDAR CARACTERISTICA DE LA VERSION / ETAPA               - Debe pertenecer a la VersionId del lote.             - Si la evaluación trabaja por etapa, debe pertenecer               exactamente a VersionFaseId.             ========================================================= */            SELECT                @TipoCriterioId =                      VC.TipoCriterioId                , @TipoCriterio =                      UPPER                      (                          LTRIM                          (                              RTRIM                              (                                  TCR.TipCritDescripcion                              )                          )                      )                , @ValorCuantitativoInicial =                      VC.ValorCuantitativoInicial                , @ValorCuantitativoFinal =                      VC.ValorCuantitativoFinal                , @ValorCuantitativoIgual =                      VC.ValorCuantitativoIgual                , @ValorCualitativo =                      VC.ValorCualitativo            FROM dbo.VERSIONCARACTERISTICA VC            INNER JOIN dbo.TIPO_CRITERIO TCR              ON TCR.TipoCriterioId =                 VC.TipoCriterioId            WHERE VC.VersCaractId =                @VersCaractId              AND VC.VersionId =                @VersionId              AND VC.Estado = 1              AND            (                @VersionFaseId IS NULL                  OR VC.VersionFaseId =                   @VersionFaseId            );              IF @TipoCriterioId IS NULL          BEGIN                IF @VersionFaseId IS NOT NULL              BEGIN                    RAISERROR(                      'La característica no pertenece a la etapa asociada a la evaluación.',                      16,                      1                  );                END              ELSE              BEGIN                    RAISERROR(                      'La característica no pertenece a la versión asociada a la evaluación.',                      16,                      1                  );                END;            END;              /* =========================================================             6. VALIDACION ESPECIAL DE REEVALUACION               Si existe EvaluacionPadreId:               SOLO se permite registrar una característica que:               1. Exista en EVALUACION_RESULTADO del padre.             2. Se encuentre ACTIVA.             3. Haya quedado Cumple = 0.               De esta forma no se puede volver a evaluar una             característica que ya cumplió.             ========================================================= */            IF @EvaluacionPadreId IS NOT NULL          BEGIN                IF NOT EXISTS              (                  SELECT 1                    FROM dbo.EVALUACION_RESULTADO ERP                    WHERE ERP.EvaluacionId =                        @EvaluacionPadreId                      AND ERP.VersCaractId =                        @VersCaractId                      AND ERP.Estado =                        'ACTIVO'                      AND ERP.Cumple = 0              )              BEGIN                    RAISERROR(                      'La característica no está habilitada para reevaluación porque no quedó NO CONFORME en la evaluación padre.',                      16,                      1                  );                END;            END;              /* =========================================================             7. DETERMINAR TIPO DE RESULTADO             ========================================================= */            IF @TipoCriterio IN          (                'MINIMO'              , 'MAXIMO'              , 'RANGO'              , 'MAYOR_QUE'              , 'MENOR_QUE'              , 'IGUAL'          )          BEGIN                SET @TipoResultado = 'NUMERICO';            END            ELSE IF @TipoCriterio IN          (                'AUSENCIA'              , 'CUALITATIVO'          )          BEGIN                SET @TipoResultado = 'TEXTO';            END            ELSE          BEGIN                RAISERROR(                  'El tipo de criterio de la característica no está soportado.',                  16,                  1              );            END;              /* =========================================================             8. VALIDAR RESULTADO SEGUN TIPO             ========================================================= */            IF @TipoResultado = 'NUMERICO'          BEGIN                IF @ResultadoNumerico IS NULL              BEGIN                    RAISERROR(                      'Debe ingresar un resultado numérico.',                      16,                      1                  );                END;                  SET @ResultadoTexto = NULL;            END          ELSE          BEGIN                IF LTRIM(RTRIM(ISNULL(@ResultadoTexto, ''))) = ''              BEGIN                    RAISERROR(                      'Debe ingresar un resultado de texto.',                      16,                      1                  );                END;                  SET @ResultadoTexto =                  LTRIM(RTRIM(@ResultadoTexto));                  SET @ResultadoNumerico = NULL;            END;              /* =========================================================             9. CALCULAR CUMPLIMIENTO             ========================================================= */            SET @CumpleCalculado = NULL;              /* =========================================================             MINIMO             Resultado >= mínimo             ========================================================= */            IF @TipoCriterio = 'MINIMO'          BEGIN                IF @ValorCuantitativoInicial IS NULL              BEGIN                    RAISERROR(                      'La especificación MINIMO no tiene valor mínimo configurado.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN @ResultadoNumerico >=                           @ValorCuantitativoInicial                          THEN 1                        ELSE 0                    END;            END;              /* =========================================================             MAXIMO             Resultado <= máximo             ========================================================= */            ELSE IF @TipoCriterio = 'MAXIMO'          BEGIN                IF @ValorCuantitativoFinal IS NULL              BEGIN                    RAISERROR(                      'La especificación MAXIMO no tiene valor máximo configurado.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN @ResultadoNumerico <=                           @ValorCuantitativoFinal                          THEN 1                        ELSE 0                    END;            END;              /* =========================================================             RANGO             mínimo <= Resultado <= máximo             ========================================================= */            ELSE IF @TipoCriterio = 'RANGO'          BEGIN                IF @ValorCuantitativoInicial IS NULL                 OR @ValorCuantitativoFinal IS NULL              BEGIN                    RAISERROR(                      'La especificación RANGO no tiene ambos límites configurados.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN @ResultadoNumerico >=                           @ValorCuantitativoInicial                         AND @ResultadoNumerico <=                           @ValorCuantitativoFinal                            THEN 1                        ELSE 0                    END;            END;              /* =========================================================             MAYOR_QUE             Resultado > límite             ========================================================= */            ELSE IF @TipoCriterio = 'MAYOR_QUE'          BEGIN                IF @ValorCuantitativoInicial IS NULL              BEGIN                    RAISERROR(                      'La especificación MAYOR_QUE no tiene límite configurado.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN @ResultadoNumerico >                           @ValorCuantitativoInicial                          THEN 1                        ELSE 0                    END;            END;              /* =========================================================             MENOR_QUE             Resultado < límite             ========================================================= */            ELSE IF @TipoCriterio = 'MENOR_QUE'          BEGIN                IF @ValorCuantitativoFinal IS NULL              BEGIN                    RAISERROR(                      'La especificación MENOR_QUE no tiene límite configurado.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN @ResultadoNumerico <                           @ValorCuantitativoFinal                          THEN 1                        ELSE 0                    END;            END;              /* =========================================================             IGUAL             Resultado = valor configurado             ========================================================= */            ELSE IF @TipoCriterio = 'IGUAL'          BEGIN                IF @ValorCuantitativoIgual IS NULL              BEGIN                    RAISERROR(                      'La especificación IGUAL no tiene valor configurado.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN @ResultadoNumerico =                           @ValorCuantitativoIgual                          THEN 1                        ELSE 0                    END;            END;              /* =========================================================             AUSENCIA             Comparación textual normalizada             ========================================================= */            ELSE IF @TipoCriterio = 'AUSENCIA'          BEGIN                IF LTRIM(RTRIM(ISNULL(@ValorCualitativo, ''))) = ''              BEGIN                    RAISERROR(                      'La especificación AUSENCIA no tiene valor cualitativo configurado.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  CASE                        WHEN UPPER                           (                               LTRIM                               (                                   RTRIM(@ResultadoTexto)                               )                           )                           =                           UPPER                           (                               LTRIM                               (                                   RTRIM(@ValorCualitativo)                               )                           )                            THEN 1                        ELSE 0                    END;            END;              /* =========================================================             CUALITATIVO               La conformidad es indicada por el evaluador.             ========================================================= */            ELSE IF @TipoCriterio = 'CUALITATIVO'          BEGIN                IF @Cumple IS NULL              BEGIN                    RAISERROR(                      'Debe indicar si el resultado cualitativo cumple la especificación.',                      16,                      1                  );                END;                  SET @CumpleCalculado =                  @Cumple;            END;              /* =========================================================             10. UPSERT RESULTADO             ========================================================= */            IF EXISTS          (              SELECT 1                FROM dbo.EVALUACION_RESULTADO                WHERE EvaluacionId =                    @EvaluacionId                  AND VersCaractId =                    @VersCaractId                  AND Estado =                    'ACTIVO'          )          BEGIN                UPDATE dbo.EVALUACION_RESULTADO                SET                    ResultadoTexto =                        @ResultadoTexto                    , ResultadoNumerico =                        @ResultadoNumerico                    , Cumple =                        @CumpleCalculado                    , FechaResultado =                        GETDATE()                    , Observacion =                        ISNULL                        (                            @Observacion,                            Observacion                        )                    , AudUsuarioModificacion =                        @Usuario                    , AudFechaActualizacion =                        GETDATE()                WHERE EvaluacionId =                    @EvaluacionId                  AND VersCaractId =                    @VersCaractId                  AND Estado =                    'ACTIVO'                  AND                (                       ISNULL(ResultadoTexto, '')                           <> ISNULL(@ResultadoTexto, '')                      OR ISNULL                       (                           ResultadoNumerico,                           -999999999                       )                       <>                       ISNULL                       (                           @ResultadoNumerico,                           -999999999                       )                      OR ISNULL                       (                           CONVERT(INT, Cumple),                           -1                       )                       <>                       ISNULL                       (                           CONVERT(INT, @CumpleCalculado),                           -1                       )                      OR ISNULL(Observacion, '')                       <>                       ISNULL                       (                           @Observacion,                           Observacion                       )                );            END          ELSE          BEGIN                INSERT INTO dbo.EVALUACION_RESULTADO              (                    EvaluacionId                  , VersCaractId                  , ResultadoTexto                  , ResultadoNumerico                  , Cumple                  , Observacion                  , Estado                  , AudUsuarioCreacion              )              VALUES              (                    @EvaluacionId                  , @VersCaractId                  , @ResultadoTexto                  , @ResultadoNumerico                  , @CumpleCalculado                  , @Observacion                  , 'ACTIVO'                  , @Usuario              );            END;              /* =========================================================             11. OBTENER RESULTADO             ========================================================= */            SELECT              @EvaluacionResultadoId =                  EvaluacionResultadoId            FROM dbo.EVALUACION_RESULTADO            WHERE EvaluacionId =                @EvaluacionId              AND VersCaractId =                @VersCaractId              AND Estado =                'ACTIVO';              /* =========================================================             12. CONFIRMAR TRANSACCION             ========================================================= */            COMMIT TRANSACTION;              /* =========================================================             13. RESPUESTA             ========================================================= */            SELECT                0 AS CodigoResultado                , CASE                    WHEN @EvaluacionPadreId IS NOT NULL                        THEN                        'Resultado de reevaluación guardado correctamente.'                    ELSE                        'Resultado guardado correctamente.'                END AS Mensaje                , @EvaluacionResultadoId                  AS EvaluacionResultadoId                , @EvaluacionId                  AS EvaluacionId                , @VersCaractId                  AS VersCaractId                , @VersionFaseId                  AS VersionFaseId                , @EvaluacionPadreId                  AS EvaluacionPadreId                , @TipoCriterio                  AS TipoCriterio                , @TipoResultado                  AS TipoResultado                , @ResultadoTexto                  AS ResultadoTexto                , @ResultadoNumerico                  AS ResultadoNumerico                , @CumpleCalculado                  AS Cumple                , @EstadoEvaluacionId                  AS EstadoEvaluacionId                , 'EN_PROCESO'                  AS EstadoEvaluacion;          END TRY      BEGIN CATCH            IF @@TRANCOUNT > 0              ROLLBACK TRANSACTION;              SELECT                -1 AS CodigoResultado              , ERROR_NUMBER() AS ErrorNumero              , ERROR_LINE() AS ErrorLinea              , ERROR_PROCEDURE() AS ErrorProcedimiento              , ERROR_MESSAGE() AS Mensaje;        END CATCH;    END;
GO
